  vm_backing_used m
    + overlap_sum (vm_maps (m_vmmaps m)) (bv_unsigned addr) (bv_unsigned addr + bv_unsigned n)
    <= vm_limit (m_vmmaps m) ->
  mprotect_budget_ok m addr n = true.
